import { Carousel } from "@/components/marketing/for-businesses/Carousel";

/**
 * AgPlatform · "One platform. Every kind of agency."
 *
 * White section, three columns — one per agency type (web design, ads,
 * SEO). Each column has an icon, a label, a plain-English description of
 * the signal it hunts on, and a short result quote. New layout (no SMB
 * equivalent); styling lives in ag.css.
 *
 * Pure server component.
 */
interface AgPlatformProps {
  t: (key: string) => string;
}

// All three icons share one style: a gradient-filled glyph (#5D7D98 → #193F45,
// top→bottom). Marketers is the supplied asset; Sales (growth chart) and
// Founders (rocket) are drawn to match. Each carries its own gradient id.
const GRAD_STOPS = (
  <>
    <stop stopColor="#5D7D98" />
    <stop offset="1" stopColor="#193F45" />
  </>
);

