const COLUMNS = [
  { key: "c1", Icon: IconSales },
  { key: "c2", Icon: IconMarketers },
  { key: "c3", Icon: IconFounders },
] as const;

export function AgPlatform({ t }: AgPlatformProps) {
  return (
    <section
      className="fb-section fb-ag-platform"
      aria-labelledby="fb-ag-platform-title"
      data-fb-tone="light"
    >
      <div className="fb-container">
        <div className="fb-board-head">
          <h2 id="fb-ag-platform-title" className="fb-h2">
            {t("platform.title_lead")}{" "}
            <em className="fb-em fb-agacc">{t("platform.title_emph")}</em>
          </h2>
          <p className="fb-sub">{t("platform.sub")}</p>
        </div>

        <Carousel
          className="fb-ag-plat-grid"
          count={COLUMNS.length}
          label={t("platform.sub")}
        >
          {COLUMNS.map(({ key, Icon }) => (
            <div key={key} className="fb-ag-plat">
              <span className="fb-ag-plat-icon" aria-hidden>
                <Icon />
              </span>
              <p className="fb-ag-plat-label">{t(`platform.${key}_label`)}</p>
              <p className="fb-ag-plat-desc">{t(`platform.${key}_desc`)}</p>
              <div className="fb-ag-plat-quote">
                <QuoteMark />
                <p className="fb-ag-plat-quote-text">
                  {t(`platform.${key}_quote`)}
                </p>
              </div>
            </div>
          ))}
        </Carousel>
      </div>
    </section>
  );
}
